import math


def family_init(ctx):
    b = ctx.bars
    n = len(b)
    N = int(ctx.p.n_win)
    if N < 4:
        N = 4
    if N % 2:
        N += 1
    ctx.N = N
    half = N // 2
    ctx.dlb = int(ctx.p.dir_lb) if int(ctx.p.dir_lb) > 0 else N
    hi = [float(x["h"]) for x in b]
    lo = [float(x["l"]) for x in b]
    d = [None] * n
    ln2 = math.log(2.0)
    for j in range(N - 1, n):
        a0 = j - N + 1
        m0 = a0 + half
        n1 = (max(hi[m0:j + 1]) - min(lo[m0:j + 1])) / half
        n2 = (max(hi[a0:m0]) - min(lo[a0:m0])) / half
        n3 = (max(hi[a0:j + 1]) - min(lo[a0:j + 1])) / N
        if n3 <= 0 or (n1 + n2) <= 0:
            continue
        v = math.log((n1 + n2) / n3) / ln2
        d[j] = 1.0 if v < 1.0 else (2.0 if v > 2.0 else v)
    ctx.d = ctx.series(d, "fractal_dim")


def signal(ctx, i):
    lb = ctx.dlb
    if i < max(ctx.N, lb) + 1:
        return 0
    d = ctx.d[i]
    if d is None:
        return 0
    thr = float(ctx.p.d_in)
    if int(ctx.p.fresh_cross):
        pd_ = ctx.d[i - 1]
        if pd_ is None or not (d < thr and pd_ >= thr):
            return 0
    elif d >= thr:
        return 0
    c = ctx.c[i]
    r = ctx.c[i - lb]
    if r is None:
        return 0
    if c > r:
        return 1
    if c < r:
        return -1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    d = ctx.d[i]
    if d is not None and d > float(ctx.p.d_out):
        return True
    lb = ctx.dlb
    if i < lb:
        return False
    r = ctx.c[i - lb]
    if r is None:
        return False
    if ctx.positions[0]["side"] == "long":
        return ctx.c[i] < r
    return ctx.c[i] > r
